 const handleUndo=async()=>{if(!undo)return;try{if(stateRef.current?.user.mode==='accounts'&&undoKind==='completion'){const current=stateRef.current.records.find(record=>record.id===undo.id);if(current)await complete(current,'open');setUndo(null);setUndoKind(null);return;}if(undoKind==='merge'){await runMerge(undo.id);}else if(undoKind==='trash'){const latest=stateRef.current?.records.find(r=>r.id===undo.id);if(latest)await saveTaskTrash(latest,false,latest.revision);}else if(undoKind==='completion'){await queued(async()=>{const current=stateRef.current?.records.find(r=>r.id===undo.id)||undo;const id=retainWrite(current,current.data,current.deleted,tr("workspace.undoCompletionResultNotYetConfirmed"),'undoComplete',{expectedRevision:current.revision});await api('/api/data',{operation:'undoComplete',id:current.id,expectedRevision:current.revision,clientOperationId:id});pendingWrites.current.delete(id);persistPendingWrites()});await refresh();}else{const latest=stateRef.current?.records.find(r=>r.id===undo.id);if(!latest||!undoAfter)throw new Error(tr("workspace.theVersionForThisChangeIsMissingKeep"));const pending:PendingWrite={id:uid(),recordId:undo.id,kind:undo.kind,base:undoAfter,desired:undo.data,deleted:undo.deleted,createdAt:new Date().toISOString(),reason:tr("workspace.versionConflictWhileUndoingAChange")};const plan=planPendingWrite(pending,latest);if(plan.state==='conflict'||plan.state==='missing'){retainWrite(undoAfter,undo.data,undo.deleted,tr("workspace.undoConflictsWithNewerFieldChanges"));throw new Error(tr("workspace.newerServerFieldsConflictWithThisUndoBoth"));}if(plan.state!=='confirmed')await save(latest,plan.data,undo.deleted,latest.revision);}setUndo(null);setUndoKind(null);notify(tr("workspace.lastChangeUndone"))}catch{}};
